SELECT COUNT(*) FROM badges as b, comments as c, posts as p, postLinks as pl, postHistory as ph, users as u WHERE c.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND b."Date"<=CAST('2014-08-20 12:16:56' AS TIMESTAMP) AND c.Score=0 AND p.Score<=67 AND ph.PostHistoryTypeId=34
